package ru.bububu.radio.core;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class C11RecoveryTest {
    static final String CODE="UNSUPPORTED_MULTIPLE_HOMOGRAPHS";
    static Article article(String id){return Article.fromSentences(id,"1",id,"Первая часть. Вторая часть. Третья часть.","Финиш.");}
    static final class Job implements PlayerController.Cancel {final long delay;final Runnable run;boolean cancelled,fired;Job(long delay,Runnable run){this.delay=delay;this.run=run;}public void cancel(){cancelled=true;}}
    static final class Voice implements PlayerController.SpeechEngine {
        final List<String> ids=new ArrayList<>(),texts=new ArrayList<>(),events=new ArrayList<>();final Set<String> badArticles=new HashSet<>();final Set<Integer> badSentences=new HashSet<>();String rejectCode=CODE;int stops;boolean stopFails;Runnable onStop;java.util.function.Function<PlayerController.SpeechSentence,List<String>> planner;
        public List<String> fragments(PlayerController.SpeechSentence s,int max){if(planner!=null)return planner.apply(s);if(badArticles.contains(s.article.id)||badSentences.contains(s.index))throw new IllegalArgumentException(rejectCode);return s.index==0?List.of("Первая часть.","Вторая часть.","Третья часть."):List.of(s.text());}
        public void speak(String text,String id){texts.add(text);ids.add(id);}
        public void stop(){stops++;if(onStop!=null)onStop.run();if(stopFails)throw new IllegalStateException("stop");}
        public void textEvent(String stage,String code,String id,long intent,PlayerController.SpeechSentence sentence,PlayerController.SpeechUnit unit){events.add(stage+":"+code+":"+sentence.index);}
        String id(){return ids.get(ids.size()-1);}
    }
    static final class Harness {
        final Voice voice=new Voice();final List<Job> jobs=new ArrayList<>();final PlayerController p;final QuickStart quick=new QuickStart();final ApplicationPlayGate app=new ApplicationPlayGate(()->0);boolean storageFails;int terminals,settlements;
        Harness(){this(false);}
        Harness(boolean two){List<Article> articles=two?List.of(article("a"),article("b")):List.of(article("a"));p=new PlayerController(List.of(new Station("S","Эфир",articles)),voice,(ms,run)->{Job j=new Job(ms,run);jobs.add(j);return j;},new PlayerController.StateStore(){public PlayerController.SavedState load(){return null;}public void save(PlayerController.SavedState state){if(storageFails)throw new IllegalStateException("storage");}},this::stateChanged,256);}
        void stateChanged(PlayerController.Snapshot s){if(quick.settleStopped(s.playing,s.seeking,s.currentRequestId)){app.cancel();settlements++;}}
        void enter(long epoch){if(epoch>=0&&!quick.playerEntered(epoch))return;p.play();}
        boolean deliver(String id,long epoch){if(!app.take(id))return false;enter(epoch);return true;}
        void complete(){String id=voice.id();p.onStart(id);p.onDone(id);}
        boolean recover(){for(Job j:jobs)if(j.delay==0&&!j.fired&&!j.cancelled){j.fired=true;j.run.run();return true;}return false;}
        void drain(int max){int count=0;while(recover())assertTrue("bounded recovery",++count<=max);}
        void local(){p.speechFailure(voice.id(),CODE,true,()->terminals++);}
    }
    @Test public void preflightRejectContinuesSameArticleAtNextSentenceWithoutHeardCoverage(){Harness h=new Harness();h.voice.badSentences.add(0);h.p.play();assertTrue(h.p.snapshot().playing);assertTrue(h.voice.ids.isEmpty());assertTrue(h.p.snapshot().completedSentences.isEmpty());assertTrue(h.recover());assertEquals("a",h.p.snapshot().article.id);assertEquals(1,h.p.snapshot().sentenceIndex);assertEquals(List.of("Финиш."),h.voice.texts);h.complete();assertEquals(List.of(1),h.p.snapshot().completedSentences);assertFalse(h.p.snapshot().read);assertFalse(h.p.snapshot().listened);assertFalse(h.p.snapshot().playing);}
    @Test public void rejectedMiddleFragmentKeepsTailButCannotCompleteWholeSentence(){Harness h=new Harness();h.p.play();h.complete();String failed=h.voice.id();h.local();assertEquals(0,h.terminals);assertEquals(2,h.voice.ids.size());h.p.onStart(failed);h.p.onDone(failed);assertEquals(2,h.voice.ids.size());assertTrue(h.recover());assertEquals("Третья часть.",h.voice.texts.get(2));h.complete();assertEquals(1,h.p.snapshot().sentenceIndex);assertTrue(h.p.snapshot().completedSentences.isEmpty());h.complete();assertEquals(List.of(1),h.p.snapshot().completedSentences);assertFalse(h.p.snapshot().listened);}
    @Test public void allInvalidArticlesAreFiniteAndNeverBecomeReadOrCompleted(){Harness h=new Harness(true);h.voice.badArticles.addAll(List.of("a","b"));h.p.play();h.drain(4);assertFalse(h.p.snapshot().playing);assertTrue(h.voice.ids.isEmpty());assertFalse(h.recover());for(PlayerController.SavedProgress progress:h.p.savedState().progress.values()){assertTrue(progress.completedSentences.isEmpty());assertFalse(progress.read);assertFalse(progress.started);assertFalse(progress.passEnded);}}
    @Test public void goodNextArticleOnlyStartsAfterCurrentExhausted(){Harness h=new Harness(true);h.voice.badArticles.add("a");h.p.play();assertTrue(h.recover());assertEquals("a",h.p.snapshot().article.id);assertEquals(1,h.p.snapshot().sentenceIndex);assertTrue(h.voice.ids.isEmpty());assertTrue(h.recover());assertEquals("b",h.p.snapshot().article.id);assertEquals(1,h.voice.ids.size());assertEquals(0,h.p.snapshot().sentenceIndex);}
    @Test public void cancellationAndLateRecoveryTaskDoNotRevivePlayback(){for(String action:List.of("pause","focus","seek","sameStation","mix")){Harness h=new Harness();h.voice.badSentences.add(0);h.p.play();Job recovery=h.jobs.stream().filter(j->j.delay==0).findFirst().orElseThrow();switch(action){case "pause":h.p.pause();break;case "focus":h.p.interrupt("Фокус потерян");break;case "seek":h.p.seekToFraction(1);h.p.pause();break;case "sameStation":h.p.selectStation("S");break;default:h.p.cancelTextRecovery();}int count=h.voice.ids.size();recovery.run.run();assertEquals(action,count,h.voice.ids.size());assertFalse(action,h.p.snapshot().playing);}}
    @Test public void unknownModelAssetIoAndUntypedMediaErrorsRemainBlocking(){for(String code:List.of("LOCAL_MODEL_UNAVAILABLE","LOCAL_PACK_NOT_READY","UNSUPPORTED_PRONUNCIATION_DATA_FORMAT","LOCAL_INPUT_PREPARATION_FAILED","UNSUPPORTED_PAGE_SIZE")){Harness h=new Harness();h.voice.rejectCode=code;h.voice.badSentences.add(0);h.p.play();assertFalse(h.p.snapshot().playing);assertFalse(h.recover());}Harness h=new Harness();h.p.play();h.p.onError(h.voice.id(),CODE);assertFalse(h.p.snapshot().playing);assertFalse(h.recover());assertFalse(LocalTextReject.known("LOGIT_NONFINITE"));assertNull(LocalTextReject.prepared("network: "+CODE));assertEquals(CODE,LocalTextReject.prepared("Silero: "+CODE));}
    @Test public void terminalPendingListenTailRunsOnlyForActualTerminalFailure(){Harness h=new Harness();h.p.play();h.local();assertEquals(0,h.terminals);assertTrue(h.recover());assertTrue(h.p.snapshot().playing);h.p.speechFailure(h.voice.id(),"IO failure",false,()->h.terminals++);assertEquals(1,h.terminals);assertFalse(h.p.snapshot().playing);}
    @Test public void failedStopOrReentrantManualPauseBlocksRecovery(){Harness h=new Harness();h.p.play();h.voice.stopFails=true;h.local();assertFalse(h.p.snapshot().playing);assertFalse(h.recover());assertEquals(1,h.voice.ids.size());Harness p=new Harness();p.p.play();p.voice.onStop=()->p.p.pause();p.voice.onStop=()->{p.voice.onStop=null;p.p.pause();};p.local();assertFalse(p.p.snapshot().playing);assertFalse(p.recover());}
    @Test public void storageFailureBeforeContinuationSubmitsNothingNew(){Harness h=new Harness();h.voice.badSentences.add(0);h.storageFails=true;h.p.play();h.drain(3);assertFalse(h.p.snapshot().playing);assertTrue(h.voice.ids.isEmpty());}
    @Test public void futurePrefetchFailureAndStaleFailureNeverTouchCurrentRequest(){Harness h=new Harness();h.p.play();h.p.onStart(h.voice.id());String current=h.voice.id();int stops=h.voice.stops;h.p.speechFailure("future",CODE,true,()->h.terminals++);assertEquals(current,h.p.snapshot().currentRequestId);assertTrue(h.p.snapshot().playing);assertEquals(stops,h.voice.stops);assertEquals(0,h.terminals);}
    @Test public void consecutiveFragmentGapsAndLastFragmentErrorDoNotAwardTheSentence(){Harness h=new Harness();h.p.play();h.complete();h.local();h.recover();h.local();h.recover();assertEquals(1,h.p.snapshot().sentenceIndex);assertTrue(h.p.snapshot().completedSentences.isEmpty());h.complete();assertEquals(List.of(1),h.p.snapshot().completedSentences);}
    static void await(Harness h){QuickStart.Candidate c=new QuickStart.Candidate("S","a","1","one","channel",ru.bububu.radio.sources.ChannelProfile.Kind.ARTICLE_ANALYSIS,true,true);QuickStart.Ticket t=h.quick.begin("run","selection","voice",List.of("one"),null,c);h.quick.ready(t,"voice");assertNotNull(h.quick.take(t,"selection","voice",x->true));assertTrue(h.quick.awaitingAudio());}
    @Test public void quietAppendBeforeAppDeliveryPreservesTheAwaitingTicket(){Harness h=new Harness();await(h);long epoch=h.quick.awaitingEpoch();String id=h.app.reserve();assertTrue(h.p.appendMaterial("S","Эфир",article("later"),null));h.stateChanged(h.p.snapshot());assertTrue("Quiet append before APP delivery is not terminal",h.quick.awaitingAudio());assertEquals(0,h.settlements);assertTrue(h.deliver(id,epoch));assertTrue(h.p.snapshot().playing);assertEquals(1,h.voice.ids.size());assertTrue(h.quick.awaitingAudio());}
    @Test public void pendingStartSurvivesRecoveryButSettlesWhenAllInputIsRejected(){Harness h=new Harness();await(h);h.voice.badSentences.add(0);h.enter(h.quick.awaitingEpoch());assertTrue(h.quick.awaitingAudio());h.recover();assertTrue(h.quick.awaitingAudio());h.p.onStart(h.voice.id());h.quick.actualStarted();assertFalse(h.quick.pending());assertTrue(h.p.snapshot().playing);Harness bad=new Harness();await(bad);bad.voice.badArticles.add("a");bad.enter(bad.quick.awaitingEpoch());bad.drain(2);assertFalse(bad.quick.pending());assertFalse(bad.p.snapshot().playing);assertEquals(1,bad.settlements);}
    @Test public void stoppedSettlementDoesNotCancelPreparationOrActivePlayback(){QuickStart q=new QuickStart();QuickStart.Ticket t=q.begin("run","s","v",List.of("one"),null,null);assertFalse(q.settleStopped(false,false,null));assertTrue(q.pending());q.revoke();Harness h=new Harness();await(h);assertFalse(h.quick.settleStopped(false,false,null));assertTrue(h.quick.playerEntered(h.quick.awaitingEpoch()));assertFalse(h.quick.settleStopped(true,false,null));assertFalse(h.quick.settleStopped(false,true,null));assertFalse(h.quick.settleStopped(false,false,"active"));assertTrue(h.quick.settleStopped(false,false,null));assertFalse(h.quick.pending());}
    @Test public void deliveredEntryThenAllInvalidSettlesOnceWithoutPausingThePlayer(){Harness h=new Harness();await(h);String id=h.app.reserve();long epoch=h.quick.awaitingEpoch();h.voice.badArticles.add("a");h.stateChanged(h.p.snapshot());assertTrue(h.quick.awaitingAudio());assertTrue(h.deliver(id,epoch));h.drain(2);assertFalse(h.quick.pending());assertEquals(1,h.settlements);assertFalse(h.p.snapshot().playing);assertTrue(h.voice.ids.isEmpty());assertEquals("Only the two rejected sentences call stop",2,h.voice.stops);int stops=h.voice.stops;h.stateChanged(h.p.snapshot());assertEquals(stops,h.voice.stops);assertEquals(1,h.settlements);assertTrue(h.p.snapshot().completedSentences.isEmpty());}
    @Test public void staleAppAndEntryEpochCannotSettleOrEnterANewerTicket(){Harness h=new Harness();await(h);String old=h.app.reserve();long oldEpoch=h.quick.awaitingEpoch();assertTrue(h.quick.playerEntered(oldEpoch));h.quick.revoke();await(h);String fresh=h.app.reserve();long freshEpoch=h.quick.awaitingEpoch();assertFalse(h.deliver(old,oldEpoch));assertFalse(h.quick.playerEntered(oldEpoch));h.enter(oldEpoch);h.stateChanged(h.p.snapshot());assertEquals(freshEpoch,h.quick.awaitingEpoch());assertTrue(h.voice.ids.isEmpty());assertEquals(0,h.settlements);assertTrue(h.deliver(fresh,freshEpoch));assertEquals(1,h.voice.ids.size());}
    @Test public void manualCancellationBeforeOrAfterEntryMakesLateAppAndMarkerInert(){for(boolean entered:List.of(false,true)){Harness h=new Harness();await(h);String id=h.app.reserve();long epoch=h.quick.awaitingEpoch();if(entered)assertTrue(h.deliver(id,epoch));h.quick.revoke();h.app.cancel();h.p.pause();int requests=h.voice.ids.size();assertFalse(h.deliver(id,epoch));assertFalse(h.quick.playerEntered(epoch));h.enter(epoch);h.stateChanged(h.p.snapshot());assertFalse(h.quick.pending());assertFalse(h.p.snapshot().playing);assertEquals(requests,h.voice.ids.size());}}
    @Test public void synchronousSystemPlayMarksOnlyItsCapturedAwaitingEpoch(){Harness h=new Harness();await(h);h.app.reserve();long epoch=h.quick.awaitingEpoch();h.app.cancel();h.voice.badArticles.add("a");h.enter(epoch);h.drain(2);assertEquals(1,h.settlements);assertFalse(h.quick.pending());assertFalse(h.p.snapshot().playing);assertTrue(h.voice.ids.isEmpty());}
    static List<AirMix.Item> pool(){return List.of(new AirMix.Item("S","a","1","one",2),new AirMix.Item("S","b","1","two",2));}
    static void route(Harness h,AirMix mix){h.p.route(new PlayerController.Route(){public void selected(String s,Article a){mix.selected(new AirMix.Item(s,a.id,a.version,s,2));}public PlayerController.RouteChoice next(String s,Article a){return next(s,a,Set.of());}public PlayerController.RouteChoice next(String s,Article a,Set<String> excluded){AirMix.Item i=mix.nextInAir(pool(),List.of("S"),s,a,h.p.savedState(),false,excluded);return i==null?PlayerController.RouteChoice.end():PlayerController.RouteChoice.item(i.station,i.article,i.version);}});}
    @Test public void explicitNewMixPassAdmitsGappedArticleAgainButPauseResumeDoesNotLoop(){
        Harness h=new Harness(true);route(h,new AirMix(new Random(3)));h.voice.badArticles.add("a");h.p.play();h.drain(2);assertEquals("b",h.p.snapshot().article.id);long errors=h.voice.events.stream().filter(x->x.startsWith("preflight_reject")).count();h.p.pause();h.p.play();for(int n=0;n<4;n++)h.complete();assertFalse(h.p.snapshot().playing);assertEquals(errors,h.voice.events.stream().filter(x->x.startsWith("preflight_reject")).count());
        Harness fresh=new Harness(true);AirMix mix=new AirMix(new Random(){@Override public int nextInt(int bound){return 0;}});route(fresh,mix);fresh.voice.badArticles.add("a");fresh.p.play();fresh.drain(2);fresh.p.onStart(fresh.voice.id());assertEquals("b",fresh.p.snapshot().article.id);
        fresh.p.pause();fresh.p.resetTextRecoveryPass();AirMix.Item first=mix.reshuffle(pool(),fresh.p.savedState());assertEquals("b",first.article);fresh.p.selectArticle(first.station,first.article);fresh.p.play();for(int n=0;n<4;n++)fresh.complete();assertEquals("a",fresh.p.snapshot().article.id);fresh.drain(2);assertFalse(fresh.p.snapshot().playing);assertTrue(fresh.p.savedState().progress.get(PlayerController.progressKey("S","a","1")).completedSentences.isEmpty());
    }
    @Test public void exclusionDoesNotDeleteMixBackHistory(){AirMix mix=new AirMix(new Random(3));PlayerController.SavedState empty=new PlayerController.SavedState("S",Map.of(),Map.of());AirMix.Item first=mix.reshuffle(pool(),empty);mix.selected(first);Set<String> excluded=Set.of(PlayerController.progressKey(first.station,first.article,first.version));AirMix.Item next=mix.nextInAir(pool(),List.of("S"),"S",article(first.article),empty,false,excluded);assertNotNull(next);mix.selected(next);assertEquals(first.key,mix.previousInAir(pool()).key);}
    @Test public void actualDecimalIntegerAndSignedInputRejectsUseTheSameBoundedRecovery(){
        for(int mode=0;mode<3;mode++){final int kind=mode;Harness h=new Harness();h.voice.planner=s->{if(s.index==0){if(kind==0)ru.bububu.radio.sources.SourceNumbers45.project("1,1234567");else if(kind==1)ru.bububu.radio.sources.SourceNumbers45.project("1234567890123");else ru.bububu.radio.models.SileroSpeechInput.project("-5");throw new AssertionError("Expected actual input rejection");}return List.of(s.text());};h.p.play();assertTrue(h.p.snapshot().playing);assertTrue(h.voice.ids.isEmpty());assertTrue(h.recover());assertEquals(1,h.p.snapshot().sentenceIndex);h.complete();assertEquals(List.of(1),h.p.snapshot().completedSentences);}
        assertTrue(LocalTextReject.known("UNSUPPORTED_SOURCE_LITERAL_U2603"));assertFalse(LocalTextReject.known("UNSUPPORTED_SOURCE_LITERAL_U123456"));assertFalse(LocalTextReject.known("UNSUPPORTED_PRONUNCIATION_DATA_IO"));assertNull(LocalTextReject.prepared("Silero: CORE_OUTPUT_SHAPE"));
    }
    @Test public void reentrantSelectionDuringStopCannotAdvanceTheNewArticle(){Harness h=new Harness(true);h.p.play();h.voice.onStop=()->{h.voice.onStop=null;h.p.selectArticle("b");};h.local();assertEquals("b",h.p.snapshot().article.id);assertEquals(0,h.p.snapshot().sentenceIndex);assertFalse(h.recover());assertEquals(2,h.voice.ids.size());assertTrue(h.p.snapshot().playing);}
    @Test public void oldPendingListenEpochCannotOwnANewTicket(){Harness h=new Harness();await(h);long old=h.quick.awaitingEpoch();assertTrue(old>=0);h.quick.revoke();await(h);assertNotEquals(old,h.quick.awaitingEpoch());assertFalse(h.quick.settleStopped(true,false,"new-request"));assertTrue(h.quick.awaitingAudio());}
    @Test public void staleMembershipBlocksQueuedRecoveryBeforeAnySubmission(){for(PlaybackMembership.Admission result:List.of(PlaybackMembership.Admission.NOT_MEMBER,PlaybackMembership.Admission.UNVERIFIED)){
        Voice voice=new Voice();voice.badSentences.add(0);List<Job> jobs=new ArrayList<>();final PlaybackMembership.Admission[] allowed={PlaybackMembership.Admission.ALLOWED};PlaybackMembership gate=new PlaybackMembership(){public Binding capture(String s,Article a){return new Binding(1,null,"HOST");}public Admission check(String s,Article a,Binding b){return allowed[0];}public boolean stationRetired(String s){return false;}};
        PlayerController p=new PlayerController(List.of(new Station("S","Эфир",List.of(article("a")))),voice,(ms,run)->{Job j=new Job(ms,run);jobs.add(j);return j;},new PlayerController.StateStore(){public PlayerController.SavedState load(){return null;}public void save(PlayerController.SavedState s){}},s->{},256,gate);p.play();allowed[0]=result;jobs.stream().filter(j->j.delay==0).findFirst().orElseThrow().run.run();assertFalse(p.snapshot().playing);assertTrue(voice.ids.isEmpty());assertTrue(p.snapshot().completedSentences.isEmpty());
    }}
}
